def compute(vars):
    inventory = vars["v1"]
    working_capital = vars["v2"]
    if working_capital == 0:
        return None
    ratio = inventory / working_capital
    value = ratio * 100
    return {
        "value": value,
        "trace": {
            "inventory": inventory,
            "working_capital": working_capital,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
